import { useEffect, useState } from 'react';
import { Box, Typography, Grid, Card, CardContent, Input, IconButton, Button } from '@mui/material';
import { Link } from 'react-router-dom';
import http from '../http';
import { AccessTime, Search, Clear, Edit } from '@mui/icons-material';
import dayjs from 'dayjs';
import global from '../global';


function Tutorials() {
  const [tutorialList, setTutorialList] = useState([]);
  const [search, setSearch] = useState('');

  const onSearchChange = (e) => setSearch(e.target.value);

  const getTutorials = () => {
    http.get('/tutorial').then((res) => {
      setTutorialList(res.data || []);
    });
  };

  const searchTutorials = () => {
    http.get(`/tutorial?search=${encodeURIComponent(search)}`).then((res) => {
      setTutorialList(res.data || []);
    });
  };

  useEffect(() => {
    getTutorials();
  }, []);

  const onSearchKeyDown = (e) => {
    if (e.key === 'Enter') {
      searchTutorials();
    }
  };

  const onClickSearch = () => {
    searchTutorials();
  };

  const onClickClear = () => {
    setSearch('');
    getTutorials();
  };

  return (
    <Box>
      <Typography variant="h5" sx={{ my: 2 }}>
        Tutorials
      </Typography>
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
        <Input
          value={search}
          placeholder="Search"
          onChange={onSearchChange}
          onKeyDown={onSearchKeyDown}
          sx={{ mr: 1 }}
        />
        <IconButton color="primary" onClick={onClickSearch}>
          <Search />
        </IconButton>
        <IconButton color="primary" onClick={onClickClear}>
          <Clear />
        </IconButton>
        <Box sx={{ flexGrow: 1 }} />
        <Link to="/addtutorial" style={{ textDecoration: 'none' }}>
          <Button variant='contained'>
            Add
          </Button>
        </Link>
      </Box>

      <Grid container spacing={2}>
        {tutorialList.length === 0 ? (
          <Grid item xs={12}>
            <Typography color="text.secondary">No tutorials available.</Typography>
          </Grid>
        ) : (
          tutorialList.map((tutorial) => (
            <Grid item xs={12} md={6} lg={4} key={tutorial.id}>
              <Card>
                <CardContent>
                  <Box sx={{ display: 'flex', mb: 1 }}>
                    <Typography variant="h6" sx={{ flexGrow: 1 }}>
                      {tutorial.title}
                    </Typography>
                    <Link to={`/edittutorial/${tutorial.id}`}>
                      <IconButton color="primary" sx={{ padding: '4px' }}>
                        <Edit />
                      </IconButton>
                    </Link>
                  </Box>

                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }} color="text.secondary">
                    <AccessTime sx={{ mr: 1 }} />
                    <Typography>
                      {dayjs(tutorial.createdAt).format(global.datetimeFormat)}
                    </Typography>
                  </Box>

                  <Typography sx={{ whiteSpace: 'pre-wrap' }}>
                    {tutorial.description}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))
        )}
      </Grid>
    </Box>
  );
}

export default Tutorials;

